/* 
   Compare two numeric substrings by decimal value.
   Leading zeros are ignored for value comparison.
   Return:
   -1 if a < b
    0 if a == b
    1 if a > b
*/
static int cmp_number(const char *a, int la, const char *b, int lb) {
    int ia = 0, ib = 0;

    while (ia < la && a[ia] == '0') ia++;
    while (ib < lb && b[ib] == '0') ib++;

    int ea = la - ia; /* effective length after removing leading zeros */
    int eb = lb - ib;

    /* both are zero */
    if (ea == 0 && eb == 0) return 0;
    if (ea < eb) return -1;
    if (ea > eb) return 1;

    for (int i = 0; i < ea; i++) {
        if (a[ia + i] < b[ib + i]) return -1;
        if (a[ia + i] > b[ib + i]) return 1;
    }
    return 0;
}

/*
   Compare filenames according to the rules:
   - split into items: maximal digit runs or single letters
   - number items come before letter items
   - letter items compared by ASCII
   - number items compared by decimal value
   - if all compared items equal and one name ends first, shorter one is smaller
*/
static int cmp_filename(const char *s, const char *t) {
    int i = 0, j = 0;
    int ns = (int)strlen(s), nt = (int)strlen(t);

    while (i < ns && j < nt) {
        int sd = isdigit((unsigned char)s[i]);
        int td = isdigit((unsigned char)t[j]);

        if (sd && td) {
            int si = i, tj = j;
            while (i < ns && isdigit((unsigned char)s[i])) i++;
            while (j < nt && isdigit((unsigned char)t[j])) j++;
            int r = cmp_number(s + si, i - si, t + tj, j - tj);
            if (r != 0) return r;
        } else if (!sd && !td) {
            if (s[i] < t[j]) return -1;
            if (s[i] > t[j]) return 1;
            i++;
            j++;
        } else {
            /* number item comes before letter item */
            return sd ? -1 : 1;
        }
    }

    if (i == ns && j == nt) return 0;
    return (i == ns) ? -1 : 1;
}

int main(void) {
    int n;
    char ref[MAXL];
    char name[MAXL];

    /*
      Assumed input format:
