int compare(const string& a, const string& b) {
    auto ta = tokenize(a);
    auto tb = tokenize(b);
    int n = min(ta.size(), tb.size());
    for (int i = 0; i < n; i++) {
        auto [ta_type, ta_val] = ta[i];
        auto [tb_type, tb_val] = tb[i];
        if (ta_type != tb_type) {
            // number (0) comes before letter (1)
            return ta_type < tb_type ? -1 : 1;
        }
        if (ta_type == 0) {
            // numeric comparison
            // remove leading zeros for comparison
            long long na = stoll(ta_val), nb = stoll(tb_val);
            if (na != nb) return na < nb ? -1 : 1;
        } else {
