struct Token {
    bool isNumber;
    string str;
    long long num;
};

vector<Token> parse(const string& s) {
    vector<Token> tokens;
    int i = 0;
    int n = s.length();

    while (i < n) {
        if (isdigit(s[i])) {
            string numStr;
            while (i < n && isdigit(s[i])) {
                numStr += s[i];
                i++;
            }
            // Remove leading zeros for numeric comparison
            string stripped = numStr;
            while (stripped.length() > 1 && stripped[0] == '0') {
                stripped = stripped.substr(1);
            }
            tokens.push_back({true, numStr, stoll(stripped)});
        } else {
            string letterStr;
            while (i < n && isalpha(s[i])) {
                letterStr += s[i];
                i++;
            }
            tokens.push_back({false, letterStr, 0});
        }
    }
    return tokens;
}

int compare(const string& a, const string& b) {
    vector<Token> tokensA = parse(a);
    vector<Token> tokensB = parse(b);

    int minLen = min(tokensA.size(), tokensB.size());

    for (int i = 0; i < minLen; i++) {
        if (tokensA[i].isNumber && !tokensB[i].isNumber) {
            return -1; // number comes before letter
        }
        if (!tokensA[i].isNumber && tokensB[i].isNumber) {
            return 1; // letter comes after number
        }

        if (tokensA[i].isNumber && tokensB[i].isNumber) {
            if (tokensA[i].num < tokensB[i].num) return -1;
            if (tokensA[i].num > tokensB[i].num) return 1;
            // If numeric values equal, compare as strings (with leading zeros)
            if (tokensA[i].str < tokensB[i].str) return -1;
            if (tokensA[i].str > tokensB[i].str) return 1;
        } else {
            if (tokensA[i].str < tokensB[i].str) return -1;
            if (tokensA[i].str > tokensB[i].str) return 1;
        }
    }

    // If all compared tokens are equal, shorter string comes first
    if (tokensA.size() < tokensB.size()) return -1;
    if (tokensA.size() > tokensB.size()) return 1;
    return 0;
}

