/*
We compare file names as sequences of items:
- maximal digit substrings -> number items
- single non-digit characters -> letter items

Ordering rules:
1) Number items come before letter items.
2) Letter items are compared by ASCII value.
3) Number items are compared by decimal value.
   If values are equal, we treat the shorter normalized representation
   as smaller; if still equal, lexicographical comparison of normalized
   strings keeps ordering deterministic.
4) Comparison proceeds item by item; if all compared items are equal,
   the shorter sequence is smaller.

For each filename after the first reference filename, output:
'+' if it should come after the reference,
'-' if it should come before the reference,
'=' if equal.
*/

struct Token {
    bool isNum;
    string s; // for letter: one char string; for number: original digit string
};

vector<Token> tokenize(const string& x) {
    vector<Token> t;
    int n = (int)x.size();
    for (int i = 0; i < n; ) {
        if (isdigit((unsigned char)x[i])) {
            int j = i;
            while (j < n && isdigit((unsigned char)x[j])) j++;
            t.push_back({true, x.substr(i, j - i)});
            i = j;
        } else {
            t.push_back({false, string(1, x[i])});
            i++;
        }
    }
    return t;
}

string stripLeadingZeros(const string& s) {
    int i = 0;
    while (i < (int)s.size() && s[i] == '0') i++;
    if (i == (int)s.size()) return "0";
    return s.substr(i);
}

int cmpNumber(const string& a, const string& b) {
    string x = stripLeadingZeros(a);
    string y = stripLeadingZeros(b);
    if (x.size() != y.size()) return x.size() < y.size() ? -1 : 1;
    if (x != y) return x < y ? -1 : 1;
    if (a.size() != b.size()) return a.size() < b.size() ? -1 : 1;
    if (a != b) return a < b ? -1 : 1;
    return 0;
}

int cmpFile(const string& A, const string& B) {
    vector<Token> a = tokenize(A), b = tokenize(B);
    int n = min((int)a.size(), (int)b.size());
    for (int i = 0; i < n; i++) {
        if (a[i].isNum != b[i].isNum) {
            return a[i].isNum ? -1 : 1; // number before letter
        }
        if (a[i].isNum) {
            int c = cmpNumber(a[i].s, b[i].s);
            if (c != 0) return c;
        } else {
            if (a[i].s[0] != b[i].s[0]) return a[i].s[0] < b[i].s[0] ? -1 : 1;
        }
    }
    if (a.size() != b.size()) return a.size() < b.size() ? -1 : 1;
    return 0;
}

