public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        sc.nextLine(); // consume the rest of the line
        String[] names = new String[n];
        for (int i = 0; i < n; i++) {
            names[i] = sc.nextLine();
        }
        String reference = sc.nextLine();

        for (String name : names) {
            int cmp = compare(name, reference);
            if (cmp < 0) {
                System.out.println("before");
            } else {
                System.out.println("after");
            }
        }
    }

    static int compare(String a, String b) {
        // Returns negative if a < b, positive if a > b, 0 if equal
        int i = 0, j = 0;
        int lenA = a.length(), lenB = b.length();

        while (i < lenA && j < lenB) {
            char ca = a.charAt(i);
            char cb = b.charAt(j);

            boolean aIsDigit = Character.isDigit(ca);
            boolean bIsDigit = Character.isDigit(cb);

            if (aIsDigit && bIsDigit) {
                // Parse the full number
                int numA = 0;
                while (i < lenA && Character.isDigit(a.charAt(i))) {
                    numA = numA * 10 + (a.charAt(i) - '0');
                    i++;
                }
                int numB = 0;
                while (j < lenB && Character.isDigit(b.charAt(j))) {
                    numB = numB * 10 + (b.charAt(j) - '0');
                    j++;
                }
                if (numA != numB) {
                    return numA - numB;
                }
            } else if (aIsDigit != bIsDigit) {
                // One is digit, other is letter: digit comes before letter
                return aIsDigit ? -1 : 1;
            } else {
                // Both letters
                if (ca != cb) {
                    return ca - cb;
                }
                i++;
                j++;
            }
        }

        // If all compared equal, shorter string comes first
        return (lenA - i) - (lenB - j);
    }
}

List<String> tokenize(String s) {
    List<String> tokens = new ArrayList<>();
    int i = 0;
    while (i < s.length()) {
        if (Character.isDigit(s.charAt(i))) {
            int j = i;
            while (j < s.length() && Character.isDigit(s.charAt(j))) j++;
            tokens.add(s.substring(i, j));
            i = j;
        } else {
            int j = i;
            while (j < s.length() && !Character.isDigit(s.charAt(j))) j++;
            tokens.add(s.substring(i, j));
            i = j;
        }
    }
    return tokens;
}

