public class Main {
    static class Token {
        boolean isNumber;
        String s;      // original token
        String norm;   // normalized numeric string (no leading zeros, "0" if all zeros)

        Token(String s, boolean isNumber) {
            this.s = s;
            this.isNumber = isNumber;
            if (isNumber) {
                this.norm = normalize(s);
            }
        }

        static String normalize(String x) {
            int i = 0;
            while (i < x.length() && x.charAt(i) == '0') i++;
            return (i == x.length()) ? "0" : x.substring(i);
        }
    }

    static List<Token> tokenize(String name) {
        List<Token> res = new ArrayList<>();
        int n = name.length();
        int i = 0;
        while (i < n) {
            char c = name.charAt(i);
            boolean digit = Character.isDigit(c);
            int j = i + 1;
            while (j < n && Character.isDigit(name.charAt(j)) == digit) j++;
            res.add(new Token(name.substring(i, j), digit));
            i = j;
        }
        return res;
    }

    static int compareNumber(Token a, Token b) {
        // compare by decimal value
        if (a.norm.length() != b.norm.length()) {
            return Integer.compare(a.norm.length(), b.norm.length());
        }
        int cmp = a.norm.compareTo(b.norm);
        if (cmp != 0) return cmp;

        // same numeric value: shorter original digit sequence first (fewer leading zeros)
        if (a.s.length() != b.s.length()) {
            return Integer.compare(a.s.length(), b.s.length());
        }

        // finally identical
        return 0;
    }

    static int compareNames(String x, String y) {
        List<Token> a = tokenize(x);
        List<Token> b = tokenize(y);

        int i = 0;
        while (i < a.size() && i < b.size()) {
            Token ta = a.get(i);
            Token tb = b.get(i);

            if (ta.isNumber != tb.isNumber) {
                return ta.isNumber ? -1 : 1; // number items come before letter items
            }

            int cmp;
            if (ta.isNumber) {
                cmp = compareNumber(ta, tb);
            } else {
                cmp = ta.s.compareTo(tb.s); // ASCII order works for Java String compareTo
            }

            if (cmp != 0) return cmp;
            i++;
        }

        return Integer.compare(a.size(), b.size());
    }

