        // from the statement, output for each file name whether it is before/after a given reference.
        // We assume the next line is the reference name.
        if (idx >= lines.size()) return;
        String ref = lines.get(idx);

        StringBuilder out = new StringBuilder();
        for (String name : names) {
            int cmp = compareNames(name, ref);
            if (cmp < 0) out.append("before");
            else if (cmp > 0) out.append("after");
            else out.append("same");
            out.append('\n');
        }

        System.out.print(out.toString());
    }
}
